export const RADIUS=96,STATION={x:204,y:19,z:-37};
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const add=(a,b)=>a.map((v,i)=>v+b[i]);export const sub=(a,b)=>a.map((v,i)=>v-b[i]);export const scale=(a,s)=>a.map(v=>v*s);export const dot=(a,b)=>a.reduce((n,v,i)=>n+v*b[i],0);export const length=a=>Math.hypot(...a);export const norm=a=>length(a)>1e-10?scale(a,1/length(a)):[0,1,0];export const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
export function basis(n){const right=norm(cross(Math.abs(n[1])>.98?[0,0,1]:[0,1,0],n));return{right,back:norm(cross(right,n))};}
export function tangent(v,n){return sub(v,scale(n,dot(v,n)));}
export function advance(n,dir,meters){const d=tangent(dir,n);if(length(d)<1e-9)return[...n];const a=meters/RADIUS;return norm(add(scale(n,Math.cos(a)),scale(norm(d),Math.sin(a))));}
export const arc=(a,b)=>Math.acos(clamp(dot(a,b),-1,1))*RADIUS;
export const SPAWN=norm([.25,.64,.74]);export const SPAWN_BASIS=basis(SPAWN);
export function heightFor(index,n){const p=PLANETS[index];if(!p.solid)return 0;if(index===2)return .12;const[x,y,z]=n;let h=(Math.sin(x*19+index)*Math.cos(z*17)+.45*Math.sin(y*33+z*11)+.19*Math.sin(x*61-y*39))*p.terrain;if(index===0){for(const c of CRATERS){const d=Math.acos(clamp(dot(n,c.n),-1,1));if(d<c.r*1.2){const q=d/c.r;h+=q<.83?-(1-q*q)*c.depth:Math.sin((q-.83)/.37*Math.PI)*c.depth*.25;}}}return h;}
export function seedRandom(seed=87231){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};}
const crng=seedRandom(52),CRATERS=Array.from({length:23},()=>({n:norm([crng()-.5,crng()-.5,crng()-.5]),r:.035+crng()*.12,depth:.3+crng()*1.3}));
export function planetPosition(i){const p=PLANETS[i];return{x:Math.cos(p.angle)*p.r,y:0,z:Math.sin(p.angle)*p.r};}
function planetState(index){const p=PLANETS[index],rng=seedRandom(901+index*8123);const crystals=[];for(let i=0;i<130;i++){let n,x,z;if(p.solid){if(i<22){const a=rng()*Math.PI*2,dir=add(scale(SPAWN_BASIS.right,Math.cos(a)),scale(SPAWN_BASIS.back,Math.sin(a)));n=advance(SPAWN,dir,7+rng()*35);}else n=norm([rng()-.5,rng()-.5,rng()-.5]);}else{x=(rng()-.5)*78;z=(rng()-.5)*78;if(Math.abs(x)<10&&Math.abs(z)<10)x+=15;}crystals.push({id:i,n,x,z,value:i%15===0?3:1});}if(p.solid){crystals[0].n=advance(SPAWN,SPAWN_BASIS.back,-7);crystals[1].n=advance(SPAWN,SPAWN_BASIS.back,-13);}else{crystals[0].x=0;crystals[0].z=-7;}return{crystals,collected:new Set(),remaining:new Map(),rover:{n:advance(SPAWN,SPAWN_BASIS.right,11),x:11,z:5,heading:[...SPAWN_BASIS.back]},rocket:{n:advance(SPAWN,add(scale(SPAWN_BASIS.right,-1),scale(SPAWN_BASIS.back,-.6)),14),x:-13,z:-8},collectedCount:0};}
export class GameState{
constructor(){this.reset();}
reset(){this.mode='foot';this.planet=3;this.n=[...SPAWN];this.x=0;this.z=3;this.alt=0;this.vy=0;this.heading=[...SPAWN_BASIS.back];this.cargo=0;this.cargoColors=Array(8).fill(0);this.deliveredColors=Array(8).fill(0);this.delivered=0;this.credits=0;this.capacity=30;this.magnet=false;this.bagLevel=0;this.energy=100;this.roverFuel=100;this.rocketFuel=100;this.target=null;this.worlds=PLANETS.map((_,i)=>planetState(i));this.visited=new Set([3]);this.space={x:185,y:8,z:14,heading:Math.PI};this.lastLanding=3;this.water=false;}
get world(){return this.worlds[this.planet];}get info(){return PLANETS[this.planet];}get solid(){return this.info.solid;}get ground(){return this.mode==='foot'||this.mode==='rover';}get fuel(){return this.mode==='foot'?this.energy:this.mode==='rover'?this.roverFuel:this.rocketFuel;}
get rover(){return this.world.rover;}get rocket(){return this.world.rocket;}get crystals(){return this.world.crystals;}get collected(){return this.world.collected;}
distanceTo(target){return this.solid?arc(this.n,target.n):Math.hypot(this.x-target.x,this.z-target.z);}
collect(){if(!this.ground||this.cargo>=this.capacity||this.alt>3)return[];const out=[],radius=this.magnet?5:this.mode==='rover'?3.6:2.1;for(const c of this.crystals){if(!this.collected.has(c.id)&&this.distanceTo(c)<radius&&this.cargo<this.capacity){const available=this.world.remaining.get(c.id)??c.value,count=Math.min(available,this.capacity-this.cargo);this.cargo+=count;this.cargoColors[this.planet]+=count;this.world.collectedCount+=count;if(count===available){this.collected.add(c.id);this.world.remaining.delete(c.id);}else this.world.remaining.set(c.id,available-count);out.push({...c,awarded:count,depleted:count===available});}}return out;}
nearbyPlanet(){let nearest=-1,d=Infinity;for(let i=0;i<PLANETS.length;i++){const p=planetPosition(i),dist=Math.hypot(this.space.x-p.x,this.space.y,this.space.z-p.z)-PLANETS[i].size;if(dist<d){d=dist;nearest=i;}}return{index:nearest,distance:d};}
interaction(){if(this.mode==='rover')return'exit';if(this.mode==='docked')return'none';if(this.mode==='flight'){const d=Math.hypot(this.space.x-STATION.x,this.space.y-STATION.y,this.space.z-STATION.z);if(d<15)return'dock';if(this.nearbyPlanet().distance<14)return'land';return'route';}const rd=this.distanceTo(this.rover),kd=this.distanceTo(this.rocket);if(kd<8&&kd<rd)return'launch';if(rd<6)return'enter';if(kd<8)return'launch';return'vehicle';}
interact(){const action=this.interaction();if(action==='exit'){this.mode='foot';if(this.solid)this.n=advance(this.n,basis(this.n).right,4);else this.x=clamp(this.x+4,-42,42);this.target=null;}if(action==='enter'){this.mode='rover';this.n=[...this.rover.n];this.x=this.rover.x;this.z=this.rover.z;this.heading=[...this.rover.heading];this.alt=0;this.target=null;}if(action==='launch')this.launch();if(action==='land')this.land(this.nearbyPlanet().index);if(action==='dock'){this.mode='docked';this.target=null;}return action;}
launch(){const p=planetPosition(this.planet);this.lastLanding=this.planet;this.mode='flight';this.space={x:p.x+PLANETS[this.planet].size+18,y:8,z:p.z+12,heading:Math.PI};this.target=null;this.alt=this.vy=0;return'launch';}
land(index){if(!Number.isInteger(index)||index<0||index>7)throw new Error('Unknown planet');this.planet=index;this.lastLanding=index;this.visited.add(index);this.mode='foot';this.n=[...SPAWN];this.x=0;this.z=3;this.heading=[...SPAWN_BASIS.back];this.alt=this.vy=0;this.target=null;this.water=false;return'land';}
setCourse(index){if(this.mode!=='flight')return false;if(index==='station'){this.target={...STATION,kind:'station'};return true;}if(!Number.isInteger(index)||index<0||index>7)return false;const p=planetPosition(index);this.target={x:p.x+PLANETS[index].size+8,y:3,z:p.z,kind:'planet',planet:index};return true;}
undock(){if(this.mode!=='docked')return false;this.mode='flight';this.space={x:STATION.x+18,y:STATION.y,z:STATION.z+4,heading:2.7};this.target=null;return true;}
deposit(){if(this.mode!=='docked'||this.cargo===0)return 0;const n=this.cargo;this.delivered+=n;this.credits+=n;for(let i=0;i<8;i++){this.deliveredColors[i]+=this.cargoColors[i];this.cargoColors[i]=0;this.worlds[i].collected.clear();this.worlds[i].remaining.clear();}this.cargo=0;return n;}
refuel(){if(this.mode!=='docked')return false;this.energy=this.roverFuel=this.rocketFuel=100;return true;}
buy(type){if(this.mode!=='docked')return false;if(type==='bag'&&this.credits>=10&&this.bagLevel<4){this.credits-=10;this.capacity+=15;this.bagLevel++;return true;}if(type==='magnet'&&this.credits>=15&&!this.magnet){this.credits-=15;this.magnet=true;return true;}return false;}
rescue(){this.mode='foot';if(this.solid)this.n=advance(this.rocket.n,basis(this.rocket.n).right,4);else{this.x=this.rocket.x+4;this.z=this.rocket.z+4;}this.alt=this.vy=0;this.target=null;this.energy=Math.max(30,this.energy);this.rocketFuel=Math.max(30,this.rocketFuel);}
step(dt,input,view={right:SPAWN_BASIS.right,back:SPAWN_BASIS.back}){dt=clamp(dt,0,.05);if(this.mode==='docked')return;const ix=input.x||0,iz=input.z||0;if(ix||iz||input.up)this.target=null;
if(this.mode==='flight'){let d=[ix,0,iz];if(this.target)d=[this.target.x-this.space.x,this.target.y-this.space.y,this.target.z-this.space.z];const size=length(d);if(this.target&&size<3.2){this.target=null;d=[0,0,0];}else if(size>0)d=scale(d,1/size);let speed=this.rocketFuel<=0?12:input.boost?100:this.target?65:32;this.space.x+=d[0]*speed*dt;this.space.z+=d[2]*speed*dt;this.space.y=clamp(this.space.y+(d[1]*speed+(input.up||0)*18)*dt,-90,140);if(size>.01)this.space.heading=Math.atan2(d[0],d[2]);this.rocketFuel=Math.max(0,this.rocketFuel-((size>.01||input.up)?.09:0)*dt);const r=Math.hypot(this.space.x,this.space.z);if(r>650){this.space.x*=649/r;this.space.z*=649/r;this.target=null;}return;}
let dir=add(scale(view.right,ix),scale(view.back,iz));let dx=ix,dz=iz;if(this.target){if(this.solid){const t=this.target.n;if(arc(this.n,t)<1.2){this.target=null;dir=[0,0,0];}else dir=tangent(t,this.n);}else{dx=this.target.x-this.x;dz=this.target.z-this.z;if(Math.hypot(dx,dz)<1.2){this.target=null;dx=dz=0;}}}
let speed=this.mode==='rover'?(input.run&&this.roverFuel>0?24:15):(input.run&&this.energy>0?10:5.8);if(this.water&&this.mode==='foot')speed*=.65;if(this.mode==='rover'&&this.roverFuel<=0)speed=7;
let moving=false;if(this.solid){dir=tangent(dir,this.n);if(length(dir)>.001){this.n=advance(this.n,dir,speed*dt);this.heading=norm(tangent(dir,this.n));moving=true;}}else{if(!this.target){dx=dot(dir,SPAWN_BASIS.right);dz=dot(dir,SPAWN_BASIS.back);}const mag=Math.hypot(dx,dz);if(mag>.001){this.x=clamp(this.x+dx/mag*speed*dt,-42,42);this.z=clamp(this.z+dz/mag*speed*dt,-42,42);this.heading=norm(add(scale(SPAWN_BASIS.right,dx),scale(SPAWN_BASIS.back,dz)));moving=true;}}
if(input.jump&&this.alt<=.001&&this.mode==='foot')this.vy=7.5;this.vy-=clamp(this.info.gravity,3.7,12)*dt;this.alt+=this.vy*dt;if(this.alt<0){this.alt=0;this.vy=0;}if(this.mode==='rover'){this.rover.n=[...this.n];this.rover.x=this.x;this.rover.z=this.z;this.rover.heading=[...this.heading];this.alt=0;if(moving)this.roverFuel=Math.max(0,this.roverFuel-.08*dt);}else{if(input.run&&moving)this.energy=Math.max(0,this.energy-.14*dt);else this.energy=Math.min(100,this.energy+.45*dt);}}
}
